// Prism grammar for Trux (.tx). Loaded on demand by Prism's autoloader for
// ```trux code blocks. The token lists mirror internal/token/token.go, the
// builtins in internal/types, and the packages in internal/stdlib; keep them
// in sync when the language grows.
Prism.languages.trux = {
  comment: { pattern: /\/\/.*/, greedy: true },
  string: {
    pattern: /"(?:\\.|[^"\\\r\n])*"/,
    greedy: true,
    inside: { escape: { pattern: /\\./, alias: "entity" } }
  },
  "package-name": {
    pattern: /\b(?:io|csv|image|time|http|gpu)(?=\.)/,
    alias: "namespace"
  },
  "class-name": /\b(?:int|float|string|bool|list|Buffer)\b/,
  keyword: /\b(?:package|import|pub|kernel|func|return|let|mut|if|else|for|break|continue|in)\b/,
  boolean: /\b(?:true|false)\b/,
  builtin: /\b(?:print|assert|len|append|clone|make)\b(?=\s*\()/,
  function: /\b[A-Za-z_]\w*(?=\s*\()/,
  number: /\b\d+(?:\.\d+)?\b/,
  operator: /==|!=|<=|>=|&&|\|\||[=!<>+\-*\/%]/,
  punctuation: /[(){}\[\],:;.]/
};
Prism.languages.tx = Prism.languages.trux;
